// Builds testing/supabase-test/install-test-project.sql: every installation file in the planned production order,
// for a NEW, EMPTY Supabase TEST project (one paste into its SQL Editor). Never for production.
//   node testing/supabase-test/build-bundle.mjs           (writes the file)
//   node testing/supabase-test/build-bundle.mjs --check   (exit 1 if the file is not up to date with the SQL files)
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "..", "..");
const { INSTALL_FILES } = await import(pathToFileURL(path.join(root, "testing/local-pg/local-db.mjs")).href);
const target = path.join(here, "install-test-project.sql");

const guard = `-- =====================================================================================================
-- install-test-project.sql — FOR A NEW, EMPTY SUPABASE *TEST* PROJECT ONLY. NEVER RUN IN PRODUCTION.
-- Generated by testing/supabase-test/build-bundle.mjs from the project's SQL files; do not edit by hand.
-- Contents, in the planned production order: ${INSTALL_FILES.join(", ")}.
-- Sheets v2 on an empty project: the keep-open list is empty (no sheet exists yet).
-- After it: run supabase-orders-v3-verify.sql and supabase-sheets-v2-verify.sql (read only), then approve the
-- test user (see testing/supabase-test/README.md).
-- =====================================================================================================

-- Safety stop: this file only runs on an empty project (no orders table yet). Production has one, so it stops there.
do $guard$
begin
  if pg_catalog.to_regclass('public.orders') is not null or pg_catalog.to_regclass('public.clients') is not null then
    raise exception 'This project is not empty (public.orders / public.clients exist). install-test-project.sql is only for a NEW, EMPTY test project. Nothing was changed.';
  end if;
end;
$guard$;
`;

let bundle = guard;
for (const name of INSTALL_FILES) {
  let sql = (await readFile(path.join(root, name), "utf8")).replace(/^﻿/, "").replace(/\r\n/g, "\n");
  if (name === "supabase-sheets-v2.sql") {
    const before = sql;
    sql = sql.replace(/insert into sheets_v2_keep_open \(sheet_number\) values \('__REPLACE_WITH_THE_ACTIVE_SHEET__'\);/, "-- (empty project: no sheet to keep open)");
    if (sql === before) throw new Error("supabase-sheets-v2.sql: the keep-open placeholder was not found");
  }
  bundle += `\n\n-- =====================================================================================================\n-- ${name}\n-- =====================================================================================================\n${sql.trimEnd()}\n`;
}

if (process.argv.includes("--check")) {
  const current = await readFile(target, "utf8").catch(() => "");
  const ok = current.replace(/\r\n/g, "\n") === bundle;
  console.log(ok ? "install-test-project.sql is up to date" : "install-test-project.sql is OUT OF DATE: run node testing/supabase-test/build-bundle.mjs");
  process.exit(ok ? 0 : 1);
}
await writeFile(target, bundle);
console.log(`wrote ${path.relative(root, target)} (${INSTALL_FILES.length} files, ${bundle.length} characters)`);
